    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                component = [(r, c)]
                visited[r][c] = True
                queue = [(r, c)]
                while queue:
