def find_outside_0s(grid):
    rows = len(grid)
    cols = len(grid[0])
    edge_cells = set()
    for r in range(rows):
        for c in [0, cols-1]:
            edge_cells.add((r, c))
    for c in range(cols):
        for r in [0, rows-1]:
            edge_cells.add((r, c))

    visited = set()
    queue = list(edge_cells)

    while queue:
        curr = queue.pop(0)
        if curr in visited or grid[curr[0]][curr[1]] == 2:
            continue
        visited.add(curr)
        r, c = curr
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if (nr, nc) in edge_cells and (nr, nc) not in visited and grid[nr][nc] == 0:
                visited.add((nr, nc))
                queue.append((nr, nc))

    return visited

