            gap_size = end - start + 1
            if gap_size >= 4:
                for c in range(start, end + 1):
                    if grid[r][c] == 0:
                        filled.append((r, c))

    # Vertical gaps of size >= 1, but NOT in horizontal gap
    for c in range(cols):
        rows_with_2 = sorted([r for r in range(len(grid)) if grid[r][c] == 2])
