def find_diamonds_fixed(grid):
    """Find diamond centers. A diamond centered at (r,c) has 2s at:
    - Top: (r-1, c)
    - Bottom: (r+1, c)
    - Left: (r, c-1)
    - Right: (r, c+1)"""
    rows, cols = len(grid), len(grid[0])
    diamonds = []

    for r in range(1, rows - 1):
        for c in range(1, cols - 1):
            top = grid[r-1][c]
            bottom = grid[r+1][c]
            left = grid[r][c-1]
            right = grid[r][c+1]

            if top == 2 and bottom == 2 and left == 2 and right == 2:
                diamonds.append((r, c))

    return diamonds

