    diamonds_by_row = {}
    for r, c in diamonds:
        if r not in diamonds_by_row:
            diamonds_by_row[r] = []
        diamonds_by_row[r].append(c)

    diamonds_by_col = {}
    for r, c in diamonds:
        if c not in diamonds_by_col:
            diamonds_by_col[c] = []
        diamonds_by_col[c].append(r)

    # Horizontal fill
    for r, cols_list in diamonds_by_row.items():
        cols_list = sorted(cols_list)
        for i in range(len(cols_list) - 1):
            c1 = cols_list[i]
            c2 = cols_list[i+1]
            gap_start = c1 + 2
            gap_end = c2 - 2
            if gap_start <= gap_end:
                for c in range(gap_start, gap_end + 1):
                    if 0 <= c < len(grid[0]):
                        filled.add((r, c))

    # Vertical fill
    for c, rows_list in diamonds_by_col.items():
        rows_list = sorted(rows_list)
        for i in range(len(rows_list) - 1):
            r1 = rows_list[i]
            r2 = rows_list[i+1]
            gap_start = r1 + 2
            gap_end = r2 - 2
            if gap_start <= gap_end:
                for r in range(gap_start, gap_end + 1):
                    if 0 <= r < len(grid):
                        filled.add((r, c))

    return sorted(filled)

